package com.donbass.mod.registry;

import com.donbass.mod.DonbassMod;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.sounds.SoundEvent;
import net.minecraftforge.registries.DeferredRegister;
import net.minecraftforge.registries.ForgeRegistries;
import net.minecraftforge.registries.RegistryObject;

/** Sound events; the .ogg files and sounds.json are generated by tools/gen_sounds.py. */
public final class ModSounds {
    public static final DeferredRegister<SoundEvent> SOUNDS =
            DeferredRegister.create(ForgeRegistries.SOUND_EVENTS, DonbassMod.MOD_ID);

    public static final RegistryObject<SoundEvent> AK_SHOT = register("item.ak_shot");
    public static final RegistryObject<SoundEvent> AK_RELOAD = register("item.ak_reload");
    public static final RegistryObject<SoundEvent> AK_EMPTY = register("item.ak_empty");
    public static final RegistryObject<SoundEvent> COAL_SET = register("armor.coal_set");
    public static final RegistryObject<SoundEvent> MILITIA_AMBIENT = register("entity.militia.ambient");
    public static final RegistryObject<SoundEvent> MILITIA_HURT = register("entity.militia.hurt");
    public static final RegistryObject<SoundEvent> MILITIA_DEATH = register("entity.militia.death");
    public static final RegistryObject<SoundEvent> MINER_AMBIENT = register("entity.miner.ambient");
    public static final RegistryObject<SoundEvent> MINER_HURT = register("entity.miner.hurt");
    public static final RegistryObject<SoundEvent> MINER_DEATH = register("entity.miner.death");
    public static final RegistryObject<SoundEvent> MINER_YES = register("entity.miner.yes");
    public static final RegistryObject<SoundEvent> MINER_NO = register("entity.miner.no");

    public static final RegistryObject<SoundEvent> DIRECTOR_AMBIENT = register("entity.director.ambient");
    public static final RegistryObject<SoundEvent> DIRECTOR_HURT = register("entity.director.hurt");
    public static final RegistryObject<SoundEvent> DIRECTOR_DEATH = register("entity.director.death");
    public static final RegistryObject<SoundEvent> DIRECTOR_ROAR = register("entity.director.roar");
    public static final RegistryObject<SoundEvent> DIRECTOR_SLAM = register("entity.director.slam");
    public static final RegistryObject<SoundEvent> DIRECTOR_SIREN = register("item.director_siren");
    public static final RegistryObject<SoundEvent> MUSIC_DIRECTOR_1 = register("music.director.phase1");
    public static final RegistryObject<SoundEvent> MUSIC_DIRECTOR_2 = register("music.director.phase2");
    public static final RegistryObject<SoundEvent> MUSIC_DIRECTOR_3 = register("music.director.phase3");

    private ModSounds() {}

    private static RegistryObject<SoundEvent> register(String name) {
        return SOUNDS.register(name,
                () -> SoundEvent.createVariableRangeEvent(new ResourceLocation(DonbassMod.MOD_ID, name)));
    }
}
